    pulse.appendChild(svgEl('animate', { attributeName: 'opacity', values: '0;0;0.9;0.2;0.9;0;0', keyTimes: '0;0.32;0.36;0.4;0.44;0.5;1', dur: D, repeatCount: 'indefinite' }));
    svg.appendChild(pulse);
