/* figures-vision-speech.js — interactive lesson figures for Phase 4 (computer
   vision) and Phase 6 (speech & audio). Loads after lesson-figures.js and
   registers widgets through window.LF. Vanilla ES5, no deps, theme via CSS
   vars. Authoring is the same fenced block in docs/en.md:
       ```figure
       convolution-kernel
       ``` */
(function () {
  'use strict';
  var LF = window.LF;
  if (!LF) { return; }
  var el = LF.el, svgEl = LF.svgEl, slider = LF.slider, select = LF.select;
  var clamp = LF.clamp;

  function shell(label, hint, grid, outKids, caption) {
    return el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, [label]), el('span', {}, [hint])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, outKids)]),
      el('div', { class: 'lf-cap' }, [caption])
    ]);
  }

  // ── convolution-kernel: slide a 3x3 kernel over a fixed 8x8 image ──────────
  function convolutionKernel(host) {
    var IMG = [
      [10, 12, 14, 80, 82, 16, 14, 12],
      [11, 13, 15, 81, 83, 17, 15, 13],
      [12, 14, 16, 82, 84, 18, 16, 14],
      [13, 15, 17, 83, 85, 19, 17, 15],
      [12, 14, 90, 90, 90, 90, 16, 14],
      [11, 13, 15, 17, 19, 17, 15, 13],
      [10, 12, 14, 16, 18, 16, 14, 12],
      [9, 11, 13, 15, 17, 15, 13, 11]
    ];
    var KERNELS = {
      identity: [[0, 0, 0], [0, 1, 0], [0, 0, 0]],
      edge: [[-1, -1, -1], [-1, 8, -1], [-1, -1, -1]],
      blur: [[1, 1, 1], [1, 1, 1], [1, 1, 1]],
      sharpen: [[0, -1, 0], [-1, 5, -1], [0, -1, 0]]
    };
    var DIV = { identity: 1, edge: 1, blur: 9, sharpen: 1 };
    var N = 8, OUT = N - 2;
    var state = { kernel: 'edge', wx: 0, wy: 0 };
    var svg = svgEl('svg', { viewBox: '0 0 520 240' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });

    function conv(ox, oy) {
      var k = KERNELS[state.kernel], s = 0, a, b;
      for (a = 0; a < 3; a++) for (b = 0; b < 3; b++) s += k[a][b] * IMG[oy + a][ox + b];
      return s / DIV[state.kernel];
    }
    function gray(v) { return clamp(v, 0, 255) / 255; }

    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var cell = 22, gx = 8, gy = 18, gx2 = 300, r, c;
      svg.appendChild(svgEl('text', { x: gx, y: 12, fill: 'var(--ink-mute,#777)', 'font-size': '10', 'font-family': 'monospace' }, [tnode('input 8x8')]));
      svg.appendChild(svgEl('text', { x: gx2, y: 12, fill: 'var(--ink-mute,#777)', 'font-size': '10', 'font-family': 'monospace' }, [tnode('output 6x6')]));
      for (r = 0; r < N; r++) for (c = 0; c < N; c++) {
        svg.appendChild(svgEl('rect', { x: gx + c * cell, y: gy + r * cell, width: cell - 1, height: cell - 1, fill: 'var(--blueprint,#3553ff)', opacity: gray(IMG[r][c]).toFixed(3) }));
      }
      var wx = state.wx, wy = state.wy;
      svg.appendChild(svgEl('rect', { x: gx + wx * cell - 1, y: gy + wy * cell - 1, width: 3 * cell, height: 3 * cell, fill: 'none', stroke: 'var(--warn,#b8870f)', 'stroke-width': '2' }));
      var ocell = 24;
      for (r = 0; r < OUT; r++) for (c = 0; c < OUT; c++) {
        var ov = conv(c, r);
        var hot = (c === wx && r === wy);
        svg.appendChild(svgEl('rect', { x: gx2 + c * ocell, y: gy + r * ocell, width: ocell - 1, height: ocell - 1, fill: 'var(--blueprint,#3553ff)', opacity: gray(ov).toFixed(3), stroke: hot ? 'var(--warn,#b8870f)' : 'none', 'stroke-width': '2' }));
      }
      var out = conv(wx, wy);
      meta.textContent = 'window at (' + wx + ',' + wy + ')  ·  output = ' + out.toFixed(1) + (DIV[state.kernel] > 1 ? '  (sum / ' + DIV[state.kernel] + ')' : '');
      var k = KERNELS[state.kernel];
      formula.textContent = 'output = Σ kernel · patch   ·   kernel rows [' + k[0].join(' ') + '] [' + k[1].join(' ') + '] [' + k[2].join(' ') + ']';
    };
    function tnode(t) { return document.createTextNode(t); }

    var grid = el('div', { class: 'lf-grid' }, [
      select(state, 'kernel', 'kernel', [['edge detect', 'edge'], ['blur (box)', 'blur'], ['sharpen', 'sharpen'], ['identity', 'identity']]),
      slider(state, 'wx', 'window x', 0, OUT - 1, 1),
      slider(state, 'wy', 'window y', 0, OUT - 1, 1)
    ]);
    host.appendChild(shell('CONVOLUTION KERNEL', 'pick a kernel, slide the window',
      grid, [svg, meta, formula],
      'A convolution lays a small kernel over every 3x3 patch of the image and sums the elementwise products. The edge kernel cancels flat regions and lights up the vertical band; blur averages neighbors; sharpen amplifies the center against its surround. The output is two pixels smaller per side because the window cannot center on the border.'));
    state._render();
  }

  // ── pooling: 2x2 max or average pooling over a 4x4 grid, stride 2 ──────────
  function pooling(host) {
    var GRID = [
      [3, 8, 2, 1],
      [5, 1, 9, 4],
      [7, 2, 6, 3],
      [1, 4, 0, 8]
    ];
    var MAXV = 9;
    var state = { mode: 'max' };
    var svg = svgEl('svg', { viewBox: '0 0 520 220' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });

    function poolWindow(br, bc) {
      var vals = [GRID[br][bc], GRID[br][bc + 1], GRID[br + 1][bc], GRID[br + 1][bc + 1]];
      if (state.mode === 'max') {
        var m = vals[0], mi = 0, i;
        for (i = 1; i < 4; i++) if (vals[i] > m) { m = vals[i]; mi = i; }
        return { val: m, contrib: mi };
      }
      var sum = vals[0] + vals[1] + vals[2] + vals[3];
      return { val: sum / 4, contrib: -1 };
    }

    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var cell = 40, gx = 14, gy = 30, gx2 = 320, r, c;
      svg.appendChild(svgEl('text', { x: gx, y: 20, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [tx('input 4x4')]));
      svg.appendChild(svgEl('text', { x: gx2, y: 20, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [tx('output 2x2')]));
      for (r = 0; r < 4; r++) for (c = 0; c < 4; c++) {
        var win = poolWindow(Math.floor(r / 2) * 2, Math.floor(c / 2) * 2);
        var local = (r % 2) * 2 + (c % 2);
        var picked = state.mode === 'max' && win.contrib === local;
        svg.appendChild(svgEl('rect', { x: gx + c * cell, y: gy + r * cell, width: cell - 2, height: cell - 2, fill: 'var(--blueprint,#3553ff)', opacity: (0.18 + 0.72 * GRID[r][c] / MAXV).toFixed(3), stroke: picked ? 'var(--warn,#b8870f)' : 'none', 'stroke-width': '2.5' }));
        svg.appendChild(svgEl('text', { x: gx + c * cell + (cell - 2) / 2, y: gy + r * cell + (cell - 2) / 2 + 4, fill: 'var(--bg,#fafaf5)', 'font-size': '13', 'font-family': 'monospace', 'text-anchor': 'middle' }, [tx(String(GRID[r][c]))]));
      }
      for (r = 0; r < 2; r++) for (c = 0; c < 2; c++) {
        var p = poolWindow(r * 2, c * 2);
        svg.appendChild(svgEl('rect', { x: gx2 + c * cell, y: gy + r * cell, width: cell - 2, height: cell - 2, fill: 'var(--blueprint,#3553ff)', opacity: (0.18 + 0.72 * p.val / MAXV).toFixed(3) }));
        svg.appendChild(svgEl('text', { x: gx2 + c * cell + (cell - 2) / 2, y: gy + r * cell + (cell - 2) / 2 + 4, fill: 'var(--bg,#fafaf5)', 'font-size': '13', 'font-family': 'monospace', 'text-anchor': 'middle' }, [tx(state.mode === 'max' ? String(p.val) : p.val.toFixed(1))]));
      }
      meta.textContent = state.mode === 'max'
        ? 'each 2x2 window keeps its largest value (outlined in the input)'
        : 'each 2x2 window keeps the average of its four values';
      formula.textContent = '2x2 window, stride 2  ·  4x4 → 2x2  ·  ' + (state.mode === 'max' ? 'out = max(window)' : 'out = mean(window)');
    };
    function tx(t) { return document.createTextNode(t); }

    var grid = el('div', { class: 'lf-grid' }, [
      select(state, 'mode', 'pooling', [['max', 'max'], ['average', 'average']])
    ]);
    host.appendChild(shell('POOLING', 'max or average',
      grid, [svg, meta, formula],
      'Pooling downsamples a feature map by summarizing each window into one value. A 2x2 window with stride 2 halves both dimensions, turning the 4x4 grid into 2x2. Max pooling forwards the strongest activation in each window (highlighted); average pooling forwards the mean. The result is smaller, translation-tolerant, and cheaper for the next layer.'));
    state._render();
  }

  // ── receptive-field: how many input pixels one deep neuron sees ────────────
  function receptiveField(host) {
    var state = { layers: 4, k: 3, stride: 1 };
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });

    state._render = function () {
      var rf = 1, jump = 1, L;
      for (L = 0; L < state.layers; L++) {
        rf = rf + (state.k - 1) * jump;
        jump = jump * state.stride;
      }
      num.innerHTML = rf + ' <small>x ' + rf + ' pixels</small>';
      meta.textContent = state.layers + ' conv layers  ·  kernel ' + state.k + '  ·  stride ' + state.stride + '  ·  one output neuron sees a ' + rf + '-pixel-wide region';
      formula.textContent = 'RF grows by (k − 1) · Π(strides) per layer   ·   RF = 1 + Σ (k − 1) · s^(layer−1)';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'layers', 'conv layers', 1, 12, 1),
      slider(state, 'k', 'kernel size', 1, 7, 2),
      slider(state, 'stride', 'stride', 1, 3, 1)
    ]);
    host.appendChild(shell('RECEPTIVE FIELD', 'stack the layers',
      grid, [num, meta, formula],
      'A neuron deep in a CNN does not see the whole image, only the patch that fed into it through every layer below. Each kernel widens that patch by (kernel − 1), and any stride multiplies the reach of all later layers. Stacking small kernels is how a network builds a large receptive field cheaply, without one giant filter.'));
    state._render();
  }

  // ── conv-output-size: floor((W - K + 2P)/S) + 1 with a strip diagram ───────
  function convOutputSize(host) {
    var state = { W: 32, K: 3, S: 1, P: 1 };
    var svg = svgEl('svg', { viewBox: '0 0 520 200' });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });

    function outSize() {
      return Math.floor((state.W - state.K + 2 * state.P) / state.S) + 1;
    }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var out = outSize();
      var valid = out >= 1 && (state.W - state.K + 2 * state.P) >= 0;
      var x0 = 30, y0 = 70, full = 460;
      var unit = full / (state.W + 2 * state.P);
      if (state.P > 0) {
        svg.appendChild(svgEl('rect', { x: x0, y: y0, width: (state.P * unit).toFixed(1), height: 40, fill: 'var(--rule-soft,#ddd)' }));
        svg.appendChild(svgEl('rect', { x: (x0 + (state.P + state.W) * unit).toFixed(1), y: y0, width: (state.P * unit).toFixed(1), height: 40, fill: 'var(--rule-soft,#ddd)' }));
      }
      svg.appendChild(svgEl('rect', { x: (x0 + state.P * unit).toFixed(1), y: y0, width: (state.W * unit).toFixed(1), height: 40, fill: 'var(--blueprint,#3553ff)', opacity: '0.22' }));
      svg.appendChild(svgEl('rect', { x: x0, y: y0, width: (state.K * unit).toFixed(1), height: 40, fill: 'none', stroke: 'var(--warn,#b8870f)', 'stroke-width': '2' }));
      var i, maxBars = Math.min(out, 64);
      for (i = 0; i < maxBars && valid; i++) {
        var cx = x0 + (i * state.S + state.K / 2) * unit;
        svg.appendChild(svgEl('circle', { cx: cx.toFixed(1), cy: y0 + 60, r: '2.4', fill: 'var(--blueprint,#3553ff)' }));
      }
      svg.appendChild(svgEl('text', { x: x0, y: y0 - 12, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [t('padded input = ' + (state.W + 2 * state.P) + ' (grey = padding, box = kernel)')]));
      svg.appendChild(svgEl('text', { x: x0, y: y0 + 90, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [t('output positions = ' + (valid ? out : 0))]));
      num.innerHTML = (valid ? out : 0) + ' <small>x ' + (valid ? out : 0) + '</small>';
      meta.textContent = valid ? 'W ' + state.W + '  K ' + state.K + '  S ' + state.S + '  P ' + state.P + '  →  ' + out + ' per side'
        : 'kernel larger than padded input: no valid output';
      formula.textContent = 'out = floor((W − K + 2P) / S) + 1 = floor((' + state.W + ' − ' + state.K + ' + ' + (2 * state.P) + ') / ' + state.S + ') + 1';
    };
    function t(s) { return document.createTextNode(s); }
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'W', 'input W', 4, 64, 1),
      slider(state, 'K', 'kernel K', 1, 11, 1),
      slider(state, 'S', 'stride S', 1, 4, 1),
      slider(state, 'P', 'padding P', 0, 5, 1)
    ]);
    host.appendChild(shell('CONV OUTPUT SIZE', 'drag W, K, S, P',
      grid, [svg, num, meta, formula],
      'The spatial size out of a convolution follows one formula: floor((W − K + 2P) / S) + 1. Padding P adds border so the kernel can reach the edges and keep size; stride S skips positions and shrinks the output. "Same" padding picks P so the output matches the input; "valid" padding uses P = 0 and shrinks by K − 1.'));
    state._render();
  }

  // ── cnn-param-count: conv weight sharing vs a dense layer ──────────────────
  function cnnParamCount(host) {
    var state = { cin: 64, cout: 128, k: 3, hw: 32 };
    var num = el('span', { class: 'lf-num' });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function human(x) { var u = ['', 'K', 'M', 'B'], i = 0; while (x >= 1000 && i < u.length - 1) { x /= 1000; i++; } return x.toFixed(x < 10 ? 2 : 1) + u[i]; }

    state._render = function () {
      var conv = (state.k * state.k * state.cin + 1) * state.cout;
      var inFeat = state.cin * state.hw * state.hw;
      var outFeat = state.cout * state.hw * state.hw;
      var dense = (inFeat + 1) * outFeat;
      var ratio = dense / conv;
      num.innerHTML = human(conv) + ' <small>conv params</small>';
      bar.style.width = clamp(state.k * state.k * state.cin * state.cout / 1e6 * 4, 2, 100) + '%';
      meta.textContent = 'a dense layer on the same ' + state.hw + 'x' + state.hw + ' map = ' + human(dense) + ' params  ·  ' + human(ratio) + 'x more';
      formula.textContent = 'conv = (K·K·Cin + 1)·Cout = (' + state.k + '·' + state.k + '·' + state.cin + ' + 1)·' + state.cout + '   ·   independent of spatial size';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'cin', 'in channels', 1, 512, 1),
      slider(state, 'cout', 'out channels', 1, 512, 1),
      slider(state, 'k', 'kernel size', 1, 7, 1),
      slider(state, 'hw', 'feature map side', 8, 64, 1)
    ]);
    host.appendChild(shell('CNN PARAM COUNT', 'conv vs dense',
      grid, [num, barWrap, meta, formula],
      'A convolution layer costs (K·K·Cin + 1)·Cout weights and reuses that one kernel at every spatial position. A dense layer wiring the same feature map would need a separate weight per input-output pixel pair, which explodes with image size. Weight sharing is why CNNs stay small enough to train on images at all.'));
    state._render();
  }

  // ── spectrogram-window: STFT window size and the time-frequency tradeoff ───
  function spectrogramWindow(host) {
    var state = { win: 256 };
    var SR = 16000;
    var svg = svgEl('svg', { viewBox: '0 0 520 220' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });

    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var W = 520, H = 220, x0 = 40, y0 = 16, gw = 440, gh = 168;
      var cols = 8, rows = 8;
      var winSec = state.win / SR;
      var freqRes = SR / state.win;
      var tFrac = clamp(state.win / 2048, 0.04, 1);
      var cw = gw / cols, ch = gh / rows;
      var r, c;
      for (r = 0; r < rows; r++) for (c = 0; c < cols; c++) {
        var timeSpread = tFrac;
        var freqSpread = 1 - tFrac;
        var op = 0.12 + 0.55 * (0.5 * timeSpread * (1 - Math.abs((c + 0.5) / cols - 0.5) * 2) + 0.5 * freqSpread * (1 - Math.abs((r + 0.5) / rows - 0.5) * 2));
        svg.appendChild(svgEl('rect', { x: x0 + c * cw, y: y0 + r * ch, width: cw - 1.5, height: ch - 1.5, fill: 'var(--blueprint,#3553ff)', opacity: clamp(op, 0.05, 0.95).toFixed(3) }));
      }
      svg.appendChild(svgEl('text', { x: x0, y: y0 + gh + 16, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [t('time →')]));
      svg.appendChild(svgEl('text', { x: 8, y: y0 + 8, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace' }, [t('freq')]));
      meta.textContent = 'window ' + state.win + ' samples = ' + (winSec * 1000).toFixed(1) + ' ms  ·  freq bins every ' + freqRes.toFixed(1) + ' Hz  ·  '
        + (state.win <= 256 ? 'sharp in time, blurry in frequency' : state.win >= 1024 ? 'sharp in frequency, blurry in time' : 'balanced');
      formula.textContent = 'time res = window / SR,  freq res = SR / window   ·   product is fixed (uncertainty)';
    };
    function t(s) { return document.createTextNode(s); }
    var grid = el('div', {}, [slider(state, 'win', 'STFT window (samples)', 64, 2048, 64)]);
    host.appendChild(shell('SPECTROGRAM WINDOW', 'drag the window size',
      grid, [svg, meta, formula],
      'A spectrogram chops the signal into windows and takes a Fourier transform of each. A short window pins down when something happened but spreads its energy across frequency; a long window resolves pitch finely but smears it across time. The product of the two resolutions is fixed, so every choice trades one for the other.'));
    state._render();
  }

  // ── mel-scale: linear Hz against the mel curve ─────────────────────────────
  function melScale(host) {
    var state = { f: 4000 };
    var FMAX = 16000;
    var W = 520, H = 220, PAD = 40;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function mel(f) { return 2595 * Math.log(1 + f / 700) / Math.LN10; }
    var MELMAX = mel(FMAX);
    function px(f) { return PAD + f / FMAX * (W - 2 * PAD); }
    function pyMel(m) { return H - PAD - m / MELMAX * (H - 2 * PAD); }

    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: PAD, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1.5', 'stroke-dasharray': '4 4' }));
      var d = '', i;
      for (i = 0; i <= 120; i++) { var f = FMAX * i / 120; d += (i ? 'L' : 'M') + px(f).toFixed(1) + ' ' + pyMel(mel(f)).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2.2' }));
      var m = mel(state.f);
      svg.appendChild(svgEl('line', { x1: px(state.f), y1: pyMel(m), x2: px(state.f), y2: H - PAD, stroke: 'var(--warn,#b8870f)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('line', { x1: PAD, y1: pyMel(m), x2: px(state.f), y2: pyMel(m), stroke: 'var(--warn,#b8870f)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('circle', { cx: px(state.f), cy: pyMel(m), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      svg.appendChild(svgEl('text', { x: W - PAD - 4, y: H - PAD - 6, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace', 'text-anchor': 'end' }, [tx('Hz →')]));
      svg.appendChild(svgEl('text', { x: PAD - 6, y: PAD + 10, fill: 'var(--ink-mute,#777)', 'font-size': '11', 'font-family': 'monospace', 'text-anchor': 'end' }, [tx('mel')]));
      num.innerHTML = Math.round(m) + ' <small>mel</small>';
      var fracHz = state.f / FMAX, fracMel = m / MELMAX;
      meta.textContent = state.f + ' Hz is ' + Math.round(fracHz * 100) + '% of the Hz axis but only ' + Math.round(fracMel * 100) + '% up the mel axis  ·  high frequencies are compressed';
      formula.textContent = 'mel = 2595 · log10(1 + f / 700)   ·   dashed line is the linear identity for comparison';
    };
    function tx(s) { return document.createTextNode(s); }
    var grid = el('div', {}, [slider(state, 'f', 'frequency (Hz)', 100, FMAX, 100)]);
    host.appendChild(shell('MEL SCALE', 'drag the frequency',
      grid, [svg, num, meta, formula],
      'Human hearing resolves low frequencies finely and high ones coarsely. The mel scale bends linear Hz to match: it is near-linear below 1 kHz and compresses steeply above it, so a jump from 8 to 9 kHz spans far fewer mels than 200 to 300 Hz. Mel filterbanks spend their resolution where the ear actually cares.'));
    state._render();
  }

  // ── nyquist-aliasing: sampling above fs/2 folds to a false low frequency ───
  function nyquistAliasing(host) {
    var state = { f: 7, fs: 20 };
    var W = 520, H = 220, PAD = 28, DUR = 1;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function px(t) { return PAD + t / DUR * (W - 2 * PAD); }
    function py(v) { return H / 2 - v * (H / 2 - PAD); }
    function aliasFreq(f, fs) {
      var fn = fs / 2;
      var m = f % fs;
      if (m > fn) m = fs - m;
      return m;
    }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: py(0), x2: W - PAD, y2: py(0), stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var d = '', i;
      for (i = 0; i <= 400; i++) { var t = DUR * i / 400; d += (i ? 'L' : 'M') + px(t).toFixed(1) + ' ' + py(Math.sin(2 * Math.PI * state.f * t)).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--rule-soft,#bbb)', 'stroke-width': '1.5' }));
      var fa = aliasFreq(state.f, state.fs);
      var over = state.f > state.fs / 2;
      var n = Math.floor(state.fs * DUR), k, sx = [], sy = [];
      for (k = 0; k <= n; k++) { var ts = k / state.fs; sx.push(ts); sy.push(Math.sin(2 * Math.PI * state.f * ts)); }
      var ad = '';
      for (k = 0; k < sx.length; k++) { ad += (k ? 'L' : 'M') + px(sx[k]).toFixed(1) + ' ' + py(sy[k]).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: ad, fill: 'none', stroke: 'var(--warn,#b8870f)', 'stroke-width': '1.5', 'stroke-dasharray': '5 3' }));
      for (k = 0; k < sx.length; k++) { svg.appendChild(svgEl('circle', { cx: px(sx[k]), cy: py(sy[k]), r: '3', fill: 'var(--blueprint,#3553ff)' })); }
      status.innerHTML = over ? 'aliased → ' + fa.toFixed(1) + ' Hz' : 'sampled cleanly';
      meta.textContent = 'signal ' + state.f + ' Hz  ·  sample rate ' + state.fs + ' Hz  ·  Nyquist = ' + (state.fs / 2) + ' Hz  ·  ' + (over ? 'above Nyquist: dots trace a false ' + fa.toFixed(1) + ' Hz wave' : 'below Nyquist: faithfully captured');
      formula.textContent = 'alias appears when f > fs/2   ·   f_alias = |f − round(f/fs)·fs|';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'f', 'signal frequency (Hz)', 1, 30, 1),
      slider(state, 'fs', 'sample rate (Hz)', 4, 40, 1)
    ]);
    host.appendChild(shell('NYQUIST & ALIASING', 'drag frequency and rate',
      grid, [svg, status, meta, formula],
      'Grey is the true signal, blue dots are the samples, the dashed line is the wave those dots imply. As long as the sample rate exceeds twice the signal frequency, the samples reconstruct the original. Push the frequency past Nyquist (fs/2) and the same dots trace a lower, false frequency: that is aliasing, and it is why audio is low-pass filtered before sampling.'));
    state._render();
  }

  LF.register({
    'convolution-kernel': convolutionKernel,
    'pooling': pooling,
    'receptive-field': receptiveField,
    'conv-output-size': convOutputSize,
    'cnn-param-count': cnnParamCount,
    'spectrogram-window': spectrogramWindow,
    'mel-scale': melScale,
    'nyquist-aliasing': nyquistAliasing
  });
})();

/* figures-alignment2.js — interactive lesson figures for Phase 18 (ethics,
   safety, alignment) and Phase 9 (reinforcement learning). Loads after
   lesson-figures.js and registers through window.LF. No deps, ES5 only,
   theme via CSS vars. */
(function () {
  'use strict';
  var LF = window.LF;
  if (!LF) { return; }
  var el = LF.el, svgEl = LF.svgEl, slider = LF.slider, select = LF.select;
  var clamp = LF.clamp, fmtInt = LF.fmtInt;

  function frame(host, label, hint, grid, outKids, caption) {
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, [label]), el('span', {}, [hint])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, outKids)]),
      el('div', { class: 'lf-cap' }, [caption])
    ]));
  }

  // ── ppo-clip: the clipped surrogate flattens updates outside [1-eps, 1+eps] ─
  function ppoClip(host) {
    var W = 520, H = 230, PAD = 34;
    var state = { adv: 1, eps: 0.2 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    var RMIN = 0, RMAX = 2;
    function clipped(r, A, eps) {
      var lo = 1 - eps, hi = 1 + eps;
      var rc = r < lo ? lo : r > hi ? hi : r;
      return A >= 0 ? Math.min(r * A, rc * A) : Math.max(r * A, rc * A);
    }
    function px(r) { return PAD + (r - RMIN) / (RMAX - RMIN) * (W - 2 * PAD); }
    function py(v, span) { return H / 2 - v / span * (H / 2 - PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var A = state.adv, eps = state.eps, span = Math.max(0.6, Math.abs(A) * (1 + eps));
      svg.appendChild(svgEl('line', { x1: PAD, y1: H / 2, x2: W - PAD, y2: H / 2, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var rx = px(1);
      svg.appendChild(svgEl('line', { x1: rx, y1: PAD, x2: rx, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      var lx = px(1 - eps), hx = px(1 + eps);
      svg.appendChild(svgEl('line', { x1: lx, y1: PAD, x2: lx, y2: H - PAD, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1', 'stroke-dasharray': '4 3' }));
      svg.appendChild(svgEl('line', { x1: hx, y1: PAD, x2: hx, y2: H - PAD, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1', 'stroke-dasharray': '4 3' }));
      var i, r, du = '', dc = '';
      for (i = 0; i <= 120; i++) { r = RMIN + (RMAX - RMIN) * i / 120; du += (i ? 'L' : 'M') + px(r).toFixed(1) + ' ' + py(r * A, span).toFixed(1) + ' '; }
      for (i = 0; i <= 120; i++) { r = RMIN + (RMAX - RMIN) * i / 120; dc += (i ? 'L' : 'M') + px(r).toFixed(1) + ' ' + py(clipped(r, A, eps), span).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: du, fill: 'none', stroke: 'var(--ink-mute,#999)', 'stroke-width': '1.5', 'stroke-dasharray': '4 3' }));
      svg.appendChild(svgEl('path', { d: dc, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2.2' }));
      var rNow = 1 + eps + (A >= 0 ? 0.35 : -0.35);
      rNow = rNow < RMIN ? RMIN : rNow > RMAX ? RMAX : rNow;
      svg.appendChild(svgEl('circle', { cx: px(rNow), cy: py(clipped(rNow, A, eps), span), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      var sign = A >= 0 ? 'positive' : 'negative';
      status.innerHTML = 'advantage ' + sign;
      meta.textContent = 'clip range [' + (1 - eps).toFixed(2) + ', ' + (1 + eps).toFixed(2) + ']  ·  ' + (A >= 0 ? 'reward good action but stop once r > 1+eps' : 'penalize bad action but stop once r < 1-eps');
      formula.textContent = 'L = min( r·A,  clip(r, 1-eps, 1+eps)·A )   ·   eps = ' + eps.toFixed(2) + ', A = ' + A.toFixed(1);
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'adv', 'advantage A', -2, 2, 0.1),
      slider(state, 'eps', 'clip epsilon', 0.05, 0.4, 0.01)
    ]);
    frame(host, 'PPO CLIP', 'drag advantage and epsilon',
      grid, [svg, el('div', { style: 'margin-top:12px' }, [status]), meta, formula],
      'PPO multiplies the advantage by the probability ratio r between the new and old policy. Grey is the raw product r·A; blue is the clipped surrogate. Once the ratio leaves the band 1-eps to 1+eps in the helpful direction, the clip flattens the objective so its gradient vanishes, keeping each update from moving the policy too far from the one that collected the data.');
    state._render();
  }

  // ── reward-model: Bradley-Terry preference, chosen scored above rejected ────
  function rewardModel(host) {
    var state = { gap: 1.2 };
    var W = 520, H = 150, PAD = 30;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function px(s) { return PAD + (s + 4) / 8 * (W - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var sChosen = state.gap / 2, sRejected = -state.gap / 2;
      var pPrefer = 1 / (1 + Math.exp(-(sChosen - sRejected)));
      var loss = -Math.log(Math.max(1e-6, pPrefer));
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var rx = px(sRejected), cx = px(sChosen), y = H - PAD;
      svg.appendChild(svgEl('line', { x1: rx, y1: y, x2: rx, y2: PAD, stroke: 'var(--ink-mute,#999)', 'stroke-width': '8' }));
      svg.appendChild(svgEl('text', { x: rx - 8, y: PAD - 6, 'text-anchor': 'end', 'font-size': '10', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode('rejected ' + sRejected.toFixed(2))]));
      svg.appendChild(svgEl('line', { x1: cx, y1: y, x2: cx, y2: PAD, stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '8' }));
      svg.appendChild(svgEl('text', { x: cx + 8, y: PAD - 6, 'text-anchor': 'start', 'font-size': '10', fill: 'var(--blueprint,#3553ff)', 'font-family': 'monospace' }, [document.createTextNode('chosen ' + sChosen.toFixed(2))]));
      num.innerHTML = (pPrefer * 100).toFixed(1) + ' <small>% P(chosen ≻ rejected)</small>';
      meta.textContent = 'score gap ' + state.gap.toFixed(2) + '  ·  preference loss ' + loss.toFixed(3) + '  ·  ' + (state.gap < 0.4 ? 'unsure: scores nearly tied' : state.gap > 2.5 ? 'confident: chosen clearly above' : 'learning the ranking');
      formula.textContent = 'P(chosen ≻ rejected) = sigmoid( r(chosen) − r(rejected) )   ·   loss = −log P';
    };
    var grid = el('div', {}, [slider(state, 'gap', 'score gap  r(chosen) − r(rejected)', 0, 4, 0.05)]);
    frame(host, 'REWARD MODEL', 'drag the score gap',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [num]), meta, formula],
      'A reward model turns human preferences into a scalar score. For each pair a human marked chosen over rejected, the Bradley-Terry objective trains the model so the chosen response scores higher. The wider the score gap, the higher the modeled probability that a human prefers the chosen answer, and the smaller the preference loss.');
    state._render();
  }

  // ── constitutional-ai: principles flag and revise a harmful response ────────
  function constitutionalAI(host) {
    var principles = [
      { name: 'harmlessness', flags: 'requests for harm', sev: 0.9 },
      { name: 'honesty', flags: 'fabricated claims', sev: 0.5 },
      { name: 'privacy', flags: 'personal data leakage', sev: 0.7 },
      { name: 'non-deception', flags: 'manipulative framing', sev: 0.4 }
    ];
    var state = { which: 0 };
    var rows = el('div', {});
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    state._render = function () {
      var which = Number(state.which);
      while (rows.firstChild) rows.removeChild(rows.firstChild);
      var p = principles[which];
      principles.forEach(function (pr, i) {
        var on = i === which;
        var bar = el('i'); bar.style.width = (pr.sev * 100).toFixed(0) + '%';
        if (!on) bar.style.background = 'var(--rule-soft,#ccc)';
        var lab = el('label', {}, [pr.name, el('b', {}, [on ? 'TRIGGERED' : 'pass'])]);
        if (!on) lab.style.opacity = '0.5';
        rows.appendChild(el('div', { class: 'lf-ctrl' }, [lab, el('div', { class: 'lf-bar' }, [bar])]));
      });
      status.innerHTML = 'revise: ' + p.flags;
      meta.textContent = 'principle "' + p.name + '" flags the draft (severity ' + p.sev.toFixed(2) + ')  ·  model critiques, then rewrites to comply';
      formula.textContent = 'response → critique against principle → revised response   ·   no human label, the constitution is the signal';
    };
    var grid = el('div', {}, [select(state, 'which', 'principle that triggers',
      principles.map(function (pr, i) { return [pr.name, String(i)]; }))]);
    frame(host, 'CONSTITUTIONAL AI', 'pick the principle',
      grid, [rows, el('div', { style: 'margin-top:12px' }, [status]), meta, formula],
      'Constitutional AI replaces a human labeller with a written set of principles. The draft response is passed through each principle; the one you select flags a violation, the model writes a critique of its own answer against that principle, then revises to comply. The revised answers become the training signal, so harmlessness is taught from rules rather than per-example human feedback.');
    state._render();
  }

  // ── actor-critic: advantage A = Q - V from the TD error drives the update ───
  function actorCritic(host) {
    var W = 520, H = 200, PAD = 32;
    var state = { td: 0.6, value: 1.0 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    var SPAN = 2.5;
    function py(v) { return H / 2 - v / SPAN * (H / 2 - PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var V = state.value, Q = V + state.td, A = Q - V;
      var baseX = PAD + 40, qX = W - PAD - 40;
      svg.appendChild(svgEl('line', { x1: PAD, y1: py(0), x2: W - PAD, y2: py(0), stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      // critic baseline V
      svg.appendChild(svgEl('line', { x1: PAD, y1: py(V), x2: W - PAD, y2: py(V), stroke: 'var(--ink-mute,#999)', 'stroke-width': '1.5', 'stroke-dasharray': '4 3' }));
      svg.appendChild(svgEl('text', { x: PAD + 4, y: py(V) - 6, 'font-size': '10', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode('V (critic) = ' + V.toFixed(2))]));
      // realized return Q
      svg.appendChild(svgEl('circle', { cx: qX, cy: py(Q), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      svg.appendChild(svgEl('text', { x: qX, y: py(Q) - 10, 'text-anchor': 'end', 'font-size': '10', fill: 'var(--blueprint,#3553ff)', 'font-family': 'monospace' }, [document.createTextNode('Q = V + delta = ' + Q.toFixed(2))]));
      // advantage bar from V to Q
      var col = A >= 0 ? 'var(--blueprint,#3553ff)' : 'var(--warn,#b8870f)';
      svg.appendChild(svgEl('line', { x1: qX, y1: py(V), x2: qX, y2: py(Q), stroke: col, 'stroke-width': '6' }));
      status.innerHTML = 'advantage A = ' + A.toFixed(2);
      meta.textContent = 'TD error delta = ' + state.td.toFixed(2) + '  ·  ' + (A > 0.05 ? 'better than expected: push the actor toward this action' : A < -0.05 ? 'worse than expected: push the actor away' : 'as expected: little update');
      formula.textContent = 'delta = r + gamma·V(s\') − V(s)   ·   A = Q − V = delta   ·   actor update ∝ A · grad log pi';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'td', 'TD error  delta', -2, 2, 0.05),
      slider(state, 'value', 'critic baseline  V', -1.5, 1.5, 0.05)
    ]);
    frame(host, 'ACTOR-CRITIC', 'drag the TD error',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [status]), meta, formula],
      'The critic estimates the value V of a state (grey baseline); the actor proposes the action that produced the return Q (blue dot). The advantage A = Q - V, which equals the one-step TD error, measures whether the action did better or worse than the critic expected. A positive advantage pushes the actor toward that action, a negative one pushes it away, and the critic moves its baseline toward the observed return.');
    state._render();
  }

  // ── interpretability-probe: probe accuracy rising through the layers ────────
  function interpretabilityProbe(host) {
    var W = 520, H = 210, PAD = 36, NL = 24;
    var state = { layer: 12, depth: 0.5 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // probe accuracy: rises with a logistic in layer index; midpoint set by depth
    function acc(layer) {
      var mid = NL * (0.2 + 0.6 * state.depth);
      var a = 0.5 + 0.48 / (1 + Math.exp(-(layer - mid) / 2.2));
      return a;
    }
    function px(l) { return PAD + l / (NL - 1) * (W - 2 * PAD); }
    function py(a) { return H - PAD - (a - 0.5) / 0.5 * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: py(0.5), x2: W - PAD, y2: py(0.5), stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      svg.appendChild(svgEl('text', { x: PAD - 4, y: py(0.5) + 3, 'text-anchor': 'end', 'font-size': '9', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode('chance')]));
      var d = '', l;
      for (l = 0; l < NL; l++) { d += (l ? 'L' : 'M') + px(l).toFixed(1) + ' ' + py(acc(l)).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2' }));
      var L = state.layer, a = acc(L);
      svg.appendChild(svgEl('line', { x1: px(L), y1: PAD, x2: px(L), y2: H - PAD, stroke: 'var(--ink-mute,#999)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('circle', { cx: px(L), cy: py(a), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      num.innerHTML = (a * 100).toFixed(1) + ' <small>% probe accuracy</small>';
      meta.textContent = 'layer ' + L + ' of ' + (NL - 1) + '  ·  ' + (a < 0.62 ? 'concept not yet linearly decodable' : a > 0.9 ? 'concept clearly present in this layer' : 'concept emerging');
      formula.textContent = 'train a linear classifier on layer activations  ·  high accuracy ⇒ the concept is linearly readable at that depth';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'layer', 'layer index', 0, NL - 1, 1),
      slider(state, 'depth', 'where the concept forms (early ↔ late)', 0, 1, 0.05)
    ]);
    frame(host, 'INTERPRETABILITY PROBE', 'drag the layer',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [num]), meta, formula],
      'A linear probe is a simple classifier trained to read a concept off a layer\'s activations. Probe accuracy near chance means the concept is not linearly decodable there; high accuracy means it is. Walking the probe deeper into the network shows the concept becoming linearly readable, which is how interpretability researchers locate where a feature like a deceptive intent first appears.');
    state._render();
  }

  // ── sae-features: dense activation decomposed into sparse features ──────────
  function saeFeatures(host) {
    var state = { l1: 1.0 };
    var feats = [0.95, 0.82, 0.74, 0.61, 0.52, 0.44, 0.36, 0.29, 0.21, 0.14, 0.09, 0.05];
    var rows = el('div', {});
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    state._render = function () {
      while (rows.firstChild) rows.removeChild(rows.firstChild);
      var thr = state.l1 * 0.18; // higher L1 -> higher activation threshold -> fewer survive
      var active = 0, recon = 0, total = 0;
      feats.forEach(function (f) { total += f; });
      feats.forEach(function (f, i) {
        var on = f >= thr;
        var val = on ? f : 0;
        if (on) { active++; recon += f; }
        var bar = el('i'); bar.style.width = (val / 0.95 * 100).toFixed(0) + '%';
        if (!on) bar.style.background = 'var(--rule-soft,#ccc)';
        var lab = el('label', {}, ['f' + (i + 1) + (on ? '' : ' ·'), el('b', {}, [on ? val.toFixed(2) : 'off'])]);
        if (!on) lab.style.opacity = '0.4';
        rows.appendChild(el('div', { class: 'lf-ctrl' }, [lab, el('div', { class: 'lf-bar' }, [bar])]));
      });
      var reconPct = recon / total * 100;
      num.innerHTML = active + ' <small>of ' + feats.length + ' features active</small>';
      meta.textContent = 'reconstruction ' + reconPct.toFixed(0) + '% of the dense vector  ·  ' + (state.l1 < 0.5 ? 'low L1: dense, polysemantic features' : state.l1 > 1.8 ? 'high L1: very sparse, may lose signal' : 'sparse and monosemantic');
      formula.textContent = 'minimize  ‖x − decode(f)‖² + lambda·‖f‖₁   ·   lambda = ' + state.l1.toFixed(2) + '   ·   higher lambda ⇒ fewer active features';
    };
    var grid = el('div', {}, [slider(state, 'l1', 'sparsity coefficient  lambda (L1)', 0.1, 2.5, 0.05)]);
    frame(host, 'SPARSE AUTOENCODER', 'drag the L1 coefficient',
      grid, [rows, el('div', { style: 'margin-top:12px' }, [num]), meta, formula],
      'A sparse autoencoder decomposes a dense activation into a much larger set of features, most of which stay off. The L1 penalty on the feature activations sets how sparse the code is. Too little and the features stay dense and polysemantic; too much and a few features carry everything but reconstruction suffers. The sweet spot gives few active, monosemantic features that each stand for one human-readable concept.');
    state._render();
  }

  // ── jailbreak-defense: attack success falls but over-refusal rises ─────────
  function jailbreakDefense(host) {
    var W = 520, H = 210, PAD = 36;
    var state = { strength: 0.5 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // attack success rate falls with defense; over-refusal on benign prompts rises
    function asr(s) { return 0.85 * Math.exp(-2.6 * s); }
    function refuse(s) { return 0.02 + 0.6 * Math.pow(s, 2.2); }
    function px(s) { return PAD + s * (W - 2 * PAD); }
    function py(v) { return H - PAD - clamp(v, 0, 1) * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      function curve(fn, st) { var d = '', i, s; for (i = 0; i <= 100; i++) { s = i / 100; d += (i ? 'L' : 'M') + px(s).toFixed(1) + ' ' + py(fn(s)).toFixed(1) + ' '; } svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: st, 'stroke-width': '2' })); }
      curve(asr, 'var(--warn,#b8870f)');
      curve(refuse, 'var(--blueprint,#3553ff)');
      var s = state.strength, a = asr(s), r = refuse(s);
      var mx = px(s);
      svg.appendChild(svgEl('line', { x1: mx, y1: PAD, x2: mx, y2: H - PAD, stroke: 'var(--ink-mute,#999)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('circle', { cx: mx, cy: py(a), r: '4.5', fill: 'var(--warn,#b8870f)' }));
      svg.appendChild(svgEl('circle', { cx: mx, cy: py(r), r: '4.5', fill: 'var(--blueprint,#3553ff)' }));
      status.innerHTML = 'attack success ' + (a * 100).toFixed(0) + '%';
      meta.textContent = 'amber: jailbreak success ' + (a * 100).toFixed(0) + '%  ·  blue: over-refusal on benign prompts ' + (r * 100).toFixed(0) + '%  ·  ' + (s < 0.3 ? 'too permissive' : s > 0.8 ? 'too restrictive' : 'balanced');
      formula.textContent = 'stronger filter ⇒ lower attack success, higher false refusals   ·   tune for the knee of both curves';
    };
    var grid = el('div', {}, [slider(state, 'strength', 'defense strength', 0, 1, 0.02)]);
    frame(host, 'JAILBREAK DEFENSE', 'drag the defense strength',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [status]), meta, formula],
      'A safety filter that blocks adversarial prompts also risks refusing harmless ones. As you turn defense strength up, the amber attack-success curve falls but the blue over-refusal curve climbs as benign requests get caught. There is no free lunch: the operating point is chosen at the knee where most jailbreaks are stopped without refusing too many legitimate users.');
    state._render();
  }

  // ── scalable-oversight: weak judge supervising strong agents via debate ─────
  function scalableOversight(host) {
    var W = 520, H = 210, PAD = 36;
    var state = { difficulty: 0.5, mode: 'debate' };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // unaided weak judge accuracy decays fast with difficulty; oversight protocols decay slower
    function direct(x) { return 0.5 + 0.45 * Math.exp(-3.2 * x); }
    function debate(x) { return 0.5 + 0.45 * Math.exp(-1.3 * x); }
    function recurse(x) { return 0.5 + 0.45 * Math.exp(-1.0 * x); }
    function aided(x) { return state.mode === 'recursion' ? recurse(x) : debate(x); }
    function px(x) { return PAD + x * (W - 2 * PAD); }
    function py(v) { return H - PAD - (v - 0.5) / 0.5 * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: py(0.5), x2: W - PAD, y2: py(0.5), stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      svg.appendChild(svgEl('text', { x: PAD - 4, y: py(0.5) + 3, 'text-anchor': 'end', 'font-size': '9', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode('chance')]));
      function curve(fn, st, dash) { var d = '', i, x; for (i = 0; i <= 100; i++) { x = i / 100; d += (i ? 'L' : 'M') + px(x).toFixed(1) + ' ' + py(fn(x)).toFixed(1) + ' '; } var a = { d: d, fill: 'none', stroke: st, 'stroke-width': '2' }; if (dash) a['stroke-dasharray'] = '4 3'; svg.appendChild(svgEl('path', a)); }
      curve(direct, 'var(--ink-mute,#999)', true);
      curve(aided, 'var(--blueprint,#3553ff)', false);
      var x = state.difficulty, vu = direct(x), va = aided(x), mx = px(x);
      svg.appendChild(svgEl('line', { x1: mx, y1: PAD, x2: mx, y2: H - PAD, stroke: 'var(--ink-mute,#999)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('circle', { cx: mx, cy: py(vu), r: '4', fill: 'var(--ink-mute,#999)' }));
      svg.appendChild(svgEl('circle', { cx: mx, cy: py(va), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      status.innerHTML = 'oversight accuracy ' + (va * 100).toFixed(0) + '%';
      meta.textContent = 'grey: judge alone ' + (vu * 100).toFixed(0) + '%  ·  blue: judge + ' + state.mode + ' ' + (va * 100).toFixed(0) + '%  ·  gain ' + ((va - vu) * 100).toFixed(0) + ' points';
      formula.textContent = state.mode === 'debate'
        ? 'two strong agents argue; the weak judge picks the more defensible answer'
        : 'task split into checkable subtasks; the weak judge verifies each piece';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'difficulty', 'task difficulty', 0, 1, 0.02),
      select(state, 'mode', 'oversight protocol', [['debate', 'debate'], ['recursion', 'recursion']])
    ]);
    frame(host, 'SCALABLE OVERSIGHT', 'drag the task difficulty',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [status]), meta, formula],
      'A weak judge cannot directly check a strong agent on hard tasks: the grey curve falls toward chance as difficulty rises. Oversight protocols help the judge keep up. In debate, two strong agents argue and the judge picks the more defensible side; in recursion, the task is decomposed into pieces the judge can verify. Either way the blue curve decays more slowly, so the judge stays above chance on tasks it could never solve alone.');
    state._render();
  }

  LF.register({
    'ppo-clip': ppoClip,
    'reward-model': rewardModel,
    'constitutional-ai': constitutionalAI,
    'actor-critic': actorCritic,
    'interpretability-probe': interpretabilityProbe,
    'sae-features': saeFeatures,
    'jailbreak-defense': jailbreakDefense,
    'scalable-oversight': scalableOversight
  });
})();

/* figures-genai-rl.js — interactive lesson figures for Phase 8 (generative AI)
   and Phase 9 (reinforcement learning). Loads after lesson-figures.js and
   registers through window.LF. No deps, ES5 only, theme via CSS vars. */
(function () {
  'use strict';
  var LF = window.LF;
  if (!LF) { return; }
  var el = LF.el, svgEl = LF.svgEl, slider = LF.slider, select = LF.select;
  var clamp = LF.clamp;

  function frame(host, label, hint, grid, outKids, caption) {
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, [label]), el('span', {}, [hint])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, outKids)]),
      el('div', { class: 'lf-cap' }, [caption])
    ]));
  }

  // ── diffusion-denoise: a 1D signal emerging as noise is stripped away ──────
  function diffusionDenoise(host) {
    var W = 520, H = 240, PAD = 30, N = 96, T = 50;
    var state = { t: 35 };
    // fixed clean signal x0 and a fixed noise sample, so render is deterministic
    var x0 = [], noise = [], i, seed = 12345;
    function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff * 2 - 1; }
    for (i = 0; i < N; i++) {
      var u = i / (N - 1);
      x0.push(0.6 * Math.sin(u * Math.PI * 2) + 0.25 * Math.sin(u * Math.PI * 6));
      noise.push(rnd());
    }
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function px(j) { return PAD + j / (N - 1) * (W - 2 * PAD); }
    function py(v) { return H / 2 - v / 1.6 * (H / 2 - PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H / 2, x2: W - PAD, y2: H / 2, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      // alpha_bar runs 1 (clean, t=0) down to ~0 (pure noise, t=T)
      var ab = Math.pow(Math.cos((state.t / T) * Math.PI / 2), 2);
      var sA = Math.sqrt(ab), sN = Math.sqrt(1 - ab), d = '', j;
      for (j = 0; j < N; j++) {
        var xt = sA * x0[j] + sN * noise[j];
        d += (j ? 'L' : 'M') + px(j).toFixed(1) + ' ' + py(xt).toFixed(1) + ' ';
      }
      // faint ghost of the clean target
      var dc = '';
      for (j = 0; j < N; j++) { dc += (j ? 'L' : 'M') + px(j).toFixed(1) + ' ' + py(x0[j]).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: dc, fill: 'none', stroke: 'var(--ink-mute,#999)', 'stroke-width': '1.5', 'stroke-dasharray': '4 3', opacity: '0.5' }));
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '1.8' }));
      meta.textContent = 't = ' + state.t + ' of ' + T + '  ·  signal ' + Math.round(sA * 100) + '%  ·  noise ' + Math.round(sN * 100) + '%  ·  ' + (state.t < 8 ? 'almost clean' : state.t > 42 ? 'near pure noise' : 'denoising');
      formula.textContent = 'x_t = sqrt(alpha_bar_t) x_0 + sqrt(1 - alpha_bar_t) noise   ·   alpha_bar_t = cos^2((t/T)·pi/2)';
    };
    var grid = el('div', {}, [slider(state, 't', 'timestep t (0 = clean, T = noise)', 0, T, 1)]);
    frame(host, 'DIFFUSION DENOISE', 'drag the timestep',
      grid, [svg, meta, formula],
      'A diffusion model learns to reverse a noising process. At t = T the signal is pure noise; as t falls toward 0 the model removes noise step by step and the underlying signal (grey dashes) re-emerges. Each x_t is a fixed mix of the clean signal and the same noise, weighted by the schedule.');
    state._render();
  }

  // ── noise-schedule: linear vs cosine alpha_bar across diffusion steps ──────
  function noiseSchedule(host) {
    var W = 520, H = 220, PAD = 32, T = 1000;
    var state = { sched: 'cosine', t: 500 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function ab(t) { return state.sched === 'cosine' ? Math.pow(Math.cos((t / T) * Math.PI / 2), 2) : Math.pow(1 - t / T, 2.2); }
    function px(t) { return PAD + t / T * (W - 2 * PAD); }
    function py(v) { return H - PAD - v * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var d = '', i, t;
      for (i = 0; i <= 160; i++) { t = T * i / 160; d += (i ? 'L' : 'M') + px(t).toFixed(1) + ' ' + py(ab(t)).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2' }));
      var mx = px(state.t), v = ab(state.t);
      svg.appendChild(svgEl('line', { x1: mx, y1: PAD, x2: mx, y2: H - PAD, stroke: 'var(--ink-mute,#999)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      svg.appendChild(svgEl('circle', { cx: mx, cy: py(v), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      var snr = v / Math.max(1e-6, 1 - v);
      meta.textContent = 'alpha_bar = ' + v.toFixed(3) + '  ·  SNR = ' + snr.toFixed(2) + '  ·  ' + (state.sched === 'cosine' ? 'cosine keeps signal longer in mid steps' : 'linear destroys signal early');
      formula.textContent = state.sched === 'cosine'
        ? 'alpha_bar_t = cos^2((t/T)·pi/2)   ·   SNR(t) = alpha_bar_t / (1 - alpha_bar_t)'
        : 'alpha_bar_t = (1 - t/T)^2.2   ·   SNR(t) = alpha_bar_t / (1 - alpha_bar_t)';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      select(state, 'sched', 'schedule', [['cosine', 'cosine'], ['linear', 'linear']]),
      slider(state, 't', 'diffusion step t', 0, T, 10)
    ]);
    frame(host, 'NOISE SCHEDULE', 'pick a schedule',
      grid, [svg, meta, formula],
      'alpha_bar is the fraction of signal surviving at step t, and its ratio to the remaining noise is the signal-to-noise ratio. A linear schedule wipes out the signal fast in the early steps; the cosine schedule decays more gently in the middle, leaving useful signal for longer and giving the model more informative intermediate targets.');
    state._render();
  }

  // ── vae-latent-grid: walk a 2D latent space, watch the decoded shape morph ─
  function vaeLatentGrid(host) {
    var W = 520, H = 240, CX = 380, CY = 120, R = 78;
    var state = { z1: 0, z2: 0 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // left: latent plane with a moving dot; right: a parametric shape decoded from (z1,z2)
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var planeX = 40, planeY = 40, planeW = 160, planeH = 160;
      svg.appendChild(svgEl('rect', { x: planeX, y: planeY, width: planeW, height: planeH, fill: 'none', stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1' }));
      svg.appendChild(svgEl('line', { x1: planeX, y1: planeY + planeH / 2, x2: planeX + planeW, y2: planeY + planeH / 2, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      svg.appendChild(svgEl('line', { x1: planeX + planeW / 2, y1: planeY, x2: planeX + planeW / 2, y2: planeY + planeH, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var dx = planeX + planeW / 2 + state.z1 / 3 * (planeW / 2);
      var dy = planeY + planeH / 2 - state.z2 / 3 * (planeH / 2);
      svg.appendChild(svgEl('circle', { cx: dx, cy: dy, r: '5', fill: 'var(--blueprint,#3553ff)' }));
      // decode: z1 controls number of lobes / pointiness, z2 controls roundness vs star
      var pts = 80, k, dpath = '';
      var lobes = 3 + Math.round((state.z1 + 3) / 6 * 5); // 3..8
      var spike = (state.z2 + 3) / 6; // 0..1
      for (k = 0; k <= pts; k++) {
        var ang = k / pts * Math.PI * 2;
        var rad = R * (1 - spike * 0.55 * Math.abs(Math.cos(lobes * ang / 2)));
        var x = CX + rad * Math.cos(ang), y = CY + rad * Math.sin(ang);
        dpath += (k ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1) + ' ';
      }
      dpath += 'Z';
      svg.appendChild(svgEl('path', { d: dpath, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2' }));
      meta.textContent = 'latent (z1, z2) = (' + state.z1.toFixed(1) + ', ' + state.z2.toFixed(1) + ')  ·  decoded ' + lobes + ' lobes  ·  ' + (spike < 0.25 ? 'round' : spike > 0.7 ? 'spiky' : 'mixed');
      formula.textContent = 'x = decoder(z),  z ~ N(0, I)   ·   nearby z decode to similar shapes (smooth latent space)';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'z1', 'latent z1', -3, 3, 0.1),
      slider(state, 'z2', 'latent z2', -3, 3, 0.1)
    ]);
    frame(host, 'VAE LATENT GRID', 'drag z1 and z2',
      grid, [svg, meta, formula],
      'A VAE maps inputs to a smooth latent space and decodes points back to outputs. The square on the left is a slice of that space; the dot is your latent code. Moving it morphs the decoded shape on the right continuously, because the decoder is trained so that nearby codes produce nearby outputs.');
    state._render();
  }

  // ── gan-minimax: generator vs discriminator balance and failure modes ──────
  function ganMinimax(host) {
    var W = 520, H = 220, PAD = 34;
    // bal: -1 = generator far ahead, 0 = equilibrium, +1 = discriminator far ahead
    var state = { bal: 0 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function px(b) { return PAD + (b + 1) / 2 * (W - 2 * PAD); }
    function py(v) { return H - PAD - clamp(v, 0, 3) / 3 * (H - 2 * PAD); }
    // D accuracy on fakes rises with bal; gradient to G vanishes when D is certain
    function dLoss(b) { return 0.4 + 0.9 * (1 - Math.abs(b)); } // lowest losses at extremes for the winner
    function gLoss(b) { return 0.5 + 1.4 * (b + 1) / 2; } // generator suffers as D gets stronger
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      // equilibrium marker at bal = 0
      var ex = px(0);
      svg.appendChild(svgEl('line', { x1: ex, y1: PAD, x2: ex, y2: H - PAD, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1', 'stroke-dasharray': '3 3' }));
      function curve(fn, st) { var d = '', i, b; for (i = 0; i <= 100; i++) { b = -1 + 2 * i / 100; d += (i ? 'L' : 'M') + px(b).toFixed(1) + ' ' + py(fn(b)).toFixed(1) + ' '; } svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: st, 'stroke-width': '2' })); }
      curve(dLoss, 'var(--ink-mute,#999)');
      curve(gLoss, 'var(--blueprint,#3553ff)');
      var b = state.bal;
      svg.appendChild(svgEl('circle', { cx: px(b), cy: py(gLoss(b)), r: '5', fill: 'var(--blueprint,#3553ff)' }));
      svg.appendChild(svgEl('circle', { cx: px(b), cy: py(dLoss(b)), r: '4', fill: 'var(--ink-mute,#999)' }));
      var mode;
      if (b > 0.55) mode = 'discriminator too strong: vanishing gradient';
      else if (b < -0.55) mode = 'generator dominates: mode collapse risk';
      else mode = 'near equilibrium: useful gradients flow';
      status.innerHTML = mode;
      meta.textContent = 'generator loss ' + gLoss(b).toFixed(2) + '  ·  discriminator loss ' + dLoss(b).toFixed(2) + '  ·  gradient to G ' + ((1 - Math.abs(b)) * 100).toFixed(0) + '%';
      formula.textContent = 'min_G max_D  E[log D(x)] + E[log(1 - D(G(z)))]   ·   balance keeps the game informative';
    };
    var grid = el('div', {}, [slider(state, 'bal', 'balance (-1 = G ahead, +1 = D ahead)', -1, 1, 0.05)]);
    frame(host, 'GAN MINIMAX', 'drag the balance',
      grid, [svg, el('div', { style: 'margin-top:12px' }, [status]), meta, formula],
      'A GAN is a two-player game: the generator (blue) tries to fool the discriminator (grey), which tries to tell real from fake. Both must improve together. If the discriminator wins decisively its gradient to the generator vanishes; if the generator races ahead it can collapse onto a few outputs. Healthy training stays near the dashed equilibrium.');
    state._render();
  }

  // ── qlearning-gridworld: 4x4 grid, value snapshots over training episodes ──
  function qlearningGridworld(host) {
    var W = 520, H = 240, GRID = 4, CELL = 52, OX = 40, OY = 18;
    var GOAL = 3, PIT = 9; // index = row*4 + col; goal at (0,3), pit at (2,1)
    var state = { ep: 200 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // converged values via value iteration on a deterministic 4x4 (gamma 0.9, step -0.04)
    var GAMMA = 0.9, STEP = -0.04, Rgoal = 1, Rpit = -1;
    function neighbors(s) {
      var r = Math.floor(s / GRID), c = s % GRID, out = [];
      if (r > 0) out.push(s - GRID); if (r < GRID - 1) out.push(s + GRID);
      if (c > 0) out.push(s - 1); if (c < GRID - 1) out.push(s + 1);
      return out;
    }
    var Vstar = []; var i;
    for (i = 0; i < GRID * GRID; i++) Vstar.push(0);
    Vstar[GOAL] = Rgoal; Vstar[PIT] = Rpit;
    (function () { var it, s, nb, best, k; for (it = 0; it < 200; it++) { for (s = 0; s < GRID * GRID; s++) { if (s === GOAL || s === PIT) continue; nb = neighbors(s); best = -1e9; for (k = 0; k < nb.length; k++) best = Math.max(best, Vstar[nb[k]]); Vstar[s] = STEP + GAMMA * best; } } })();
    function valueAt(s, ep) { if (s === GOAL) return Rgoal; if (s === PIT) return Rpit; return Vstar[s] * clamp(ep / 300, 0, 1); }
    function shade(v) {
      // map v in [-1,1] to opacity of blueprint (positive) or warn (negative)
      if (v >= 0) return { fill: 'var(--blueprint,#3553ff)', op: (0.08 + 0.6 * Math.min(1, v)).toFixed(2) };
      return { fill: 'var(--warn,#b8870f)', op: (0.08 + 0.6 * Math.min(1, -v)).toFixed(2) };
    }
    function bestDir(s, ep) {
      var nb = neighbors(s), best = -1e9, dir = null, k;
      for (k = 0; k < nb.length; k++) { var vv = valueAt(nb[k], ep); if (vv > best) { best = vv; dir = nb[k]; } }
      return dir;
    }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var s, r, c;
      for (s = 0; s < GRID * GRID; s++) {
        r = Math.floor(s / GRID); c = s % GRID;
        var x = OX + c * CELL, y = OY + r * CELL;
        var v = valueAt(s, state.ep), sh = shade(v);
        svg.appendChild(svgEl('rect', { x: x, y: y, width: CELL, height: CELL, fill: sh.fill, opacity: sh.op, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1' }));
        var cx = x + CELL / 2, cy = y + CELL / 2;
        if (s === GOAL) { svg.appendChild(svgEl('text', { x: cx, y: cy + 4, 'text-anchor': 'middle', 'font-size': '12', fill: 'var(--ink,#1a1a1a)', 'font-family': 'monospace' }, [document.createTextNode('GOAL')])); }
        else if (s === PIT) { svg.appendChild(svgEl('text', { x: cx, y: cy + 4, 'text-anchor': 'middle', 'font-size': '13', fill: 'var(--ink,#1a1a1a)', 'font-family': 'monospace' }, [document.createTextNode('PIT')])); }
        else {
          svg.appendChild(svgEl('text', { x: cx, y: y + CELL - 6, 'text-anchor': 'middle', 'font-size': '9', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode(v.toFixed(2))]));
          if (state.ep > 20) {
            var dir = bestDir(s, state.ep);
            if (dir != null) {
              var dr = Math.floor(dir / GRID) - r, dc = (dir % GRID) - c;
              var ax = cx + dc * 14, ay = (cy - 4) + dr * 14;
              svg.appendChild(svgEl('line', { x1: cx, y1: cy - 4, x2: ax, y2: ay, stroke: 'var(--ink,#1a1a1a)', 'stroke-width': '1.6' }));
              svg.appendChild(svgEl('circle', { cx: ax, cy: ay, r: '2.4', fill: 'var(--ink,#1a1a1a)' }));
            }
          }
        }
      }
      meta.textContent = 'episode ' + state.ep + ' of 300  ·  ' + (state.ep < 30 ? 'values still near zero' : state.ep < 200 ? 'value spreading from the goal' : 'policy converged');
      formula.textContent = 'Q(s,a) <- Q(s,a) + alpha [ r + gamma max_a\' Q(s\',a\') - Q(s,a) ]   ·   gamma = 0.9';
    };
    var grid = el('div', {}, [slider(state, 'ep', 'training episodes', 0, 300, 10)]);
    frame(host, 'Q-LEARNING GRIDWORLD', 'drag the episodes',
      grid, [svg, meta, formula],
      'The agent learns to reach the goal and avoid the pit. Cell shading is the learned state value (blue good, amber bad) and the arrows are the greedy policy. Early on values sit near zero; with training, value propagates outward from the goal and the arrows line up into a path that routes around the pit.');
    state._render();
  }

  // ── value-iteration-gamma: value propagating along a 1D chain toward a goal ─
  function valueIterationGamma(host) {
    var W = 520, H = 200, N = 10, CELL = 44, OX = 36, OY = 70;
    var state = { gamma: 0.9 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // goal at the rightmost cell, reward 1; each step costs nothing; V(s) = gamma^(dist)
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var g = state.gamma, i, vals = [];
      for (i = 0; i < N; i++) vals.push(Math.pow(g, (N - 1 - i)));
      for (i = 0; i < N; i++) {
        var x = OX + i * CELL, y = OY, v = vals[i];
        var op = (0.08 + 0.7 * v).toFixed(2);
        svg.appendChild(svgEl('rect', { x: x, y: y, width: CELL - 4, height: CELL - 4, fill: 'var(--blueprint,#3553ff)', opacity: op, stroke: 'var(--rule-soft,#ddd)', 'stroke-width': '1' }));
        var cx = x + (CELL - 4) / 2;
        svg.appendChild(svgEl('text', { x: cx, y: y + (CELL - 4) / 2 + 4, 'text-anchor': 'middle', 'font-size': '9', fill: 'var(--ink,#1a1a1a)', 'font-family': 'monospace' }, [document.createTextNode(v.toFixed(2))]));
        if (i === N - 1) svg.appendChild(svgEl('text', { x: cx, y: y - 8, 'text-anchor': 'middle', 'font-size': '10', fill: 'var(--ink-mute,#777)', 'font-family': 'monospace' }, [document.createTextNode('GOAL')]));
        if (i < N - 1) { svg.appendChild(svgEl('line', { x1: x + CELL - 6, y1: y + (CELL - 4) / 2, x2: x + CELL + 2, y2: y + (CELL - 4) / 2, stroke: 'var(--ink-mute,#999)', 'stroke-width': '1.2' })); }
      }
      var reach = vals[0];
      meta.textContent = 'gamma = ' + g.toFixed(2) + '  ·  value 9 steps from goal = ' + reach.toFixed(3) + '  ·  ' + (g < 0.6 ? 'short-sighted: distant reward fades' : g > 0.95 ? 'far-sighted: value carries across the chain' : 'moderate horizon');
      formula.textContent = 'V(s) = gamma^(distance to goal)   ·   higher gamma propagates value further from the goal';
    };
    var grid = el('div', {}, [slider(state, 'gamma', 'discount gamma', 0.1, 0.99, 0.01)]);
    frame(host, 'VALUE ITERATION', 'drag gamma',
      grid, [svg, meta, formula],
      'Value iteration backs reward up from the goal one step at a time. On this chain the only reward is at the rightmost cell, so each state is worth gamma raised to its distance from the goal. A small gamma makes distant reward nearly worthless (short-sighted); a gamma near 1 carries strong value all the way back along the chain.');
    state._render();
  }

  // ── epsilon-greedy: explore/exploit split and cumulative regret ────────────
  function epsilonGreedy(host) {
    var W = 520, H = 210, PAD = 32, N = 500;
    var state = { eps: 0.1, decay: 1 }; // decay 1 = fixed, 0 = decaying schedule
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function epsAt(t) { return state.decay > 0.5 ? state.eps : state.eps / (1 + t / 60); }
    function px(t) { return PAD + t / N * (W - 2 * PAD); }
    function py(v, vmax) { return H - PAD - clamp(v / vmax, 0, 1) * (H - 2 * PAD); }
    var GAP = 0.4; // regret cost per exploratory pull (suboptimal arm)
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var t, regret = 0, pts = [], vmax = 1e-6;
      for (t = 0; t <= N; t++) { regret += epsAt(t) * GAP; pts.push(regret); }
      vmax = pts[N];
      var d = '';
      for (t = 0; t <= N; t += 5) { d += (t ? 'L' : 'M') + px(t).toFixed(1) + ' ' + py(pts[t], vmax).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '2' }));
      var e0 = epsAt(0), eEnd = epsAt(N);
      bar.style.width = (e0 * 100).toFixed(0) + '%';
      meta.textContent = 'start explore ' + Math.round(e0 * 100) + '% / exploit ' + Math.round((1 - e0) * 100) + '%  ·  end explore ' + Math.round(eEnd * 100) + '%  ·  total regret ' + vmax.toFixed(1);
      formula.textContent = state.decay > 0.5
        ? 'fixed epsilon: regret grows linearly forever  ·  P(explore) = ' + state.eps.toFixed(2)
        : 'decaying epsilon_t = epsilon_0 / (1 + t/60)  ·  regret levels off as exploration fades';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'eps', 'epsilon (explore rate)', 0, 0.5, 0.01),
      select(state, 'decay', 'schedule', [['fixed', '1'], ['decaying', '0']])
    ]);
    frame(host, 'EPSILON-GREEDY', 'drag epsilon',
      grid, [el('div', { class: 'lf-meta' }, ['explore share of actions']), barWrap, svg, meta, formula],
      'With probability epsilon the agent explores a random action; otherwise it exploits its current best estimate. The bar shows the explore/exploit split and the curve is cumulative regret, the reward given up by not always picking the best arm. A fixed epsilon piles up regret forever; a decaying schedule explores early then exploits, so regret flattens.');
    state._render();
  }

  // ── discount-horizon: effective horizon and geometric weight decay ─────────
  function discountHorizon(host) {
    var W = 520, H = 210, PAD = 32, TMAX = 40;
    var state = { gamma: 0.9 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    function px(t) { return PAD + t / TMAX * (W - 2 * PAD); }
    function py(w) { return H - PAD - w * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(svgEl('line', { x1: PAD, y1: H - PAD, x2: W - PAD, y2: H - PAD, stroke: 'var(--rule-soft,#eee)', 'stroke-width': '1' }));
      var g = state.gamma, t;
      for (t = 0; t <= TMAX; t++) {
        var w = Math.pow(g, t);
        svg.appendChild(svgEl('rect', { x: px(t) - 3, y: py(w), width: 6, height: (H - PAD) - py(w), fill: 'var(--blueprint,#3553ff)', opacity: '0.85' }));
      }
      var hor = 1 / (1 - g);
      // mark the effective horizon
      var hx = px(Math.min(TMAX, hor));
      svg.appendChild(svgEl('line', { x1: hx, y1: PAD, x2: hx, y2: H - PAD, stroke: 'var(--warn,#b8870f)', 'stroke-width': '1.5', 'stroke-dasharray': '4 3' }));
      num.innerHTML = hor.toFixed(1) + ' <small>step horizon</small>';
      meta.textContent = 'gamma = ' + g.toFixed(2) + '  ·  weight at the horizon = ' + Math.pow(g, hor).toFixed(2) + ' (about 1/e)  ·  reward 20 steps out weighs ' + Math.pow(g, 20).toFixed(3);
      formula.textContent = 'return = sum_t gamma^t r_t   ·   effective horizon = 1/(1 - gamma)   ·   weights decay geometrically';
    };
    var grid = el('div', {}, [slider(state, 'gamma', 'discount gamma', 0.5, 0.99, 0.01)]);
    frame(host, 'DISCOUNT HORIZON', 'drag gamma',
      grid, [svg, el('div', { style: 'margin-top:10px' }, [num]), meta, formula],
      'Future reward t steps away is weighted by gamma^t, so the weights fall off geometrically (the bars). The dashed line marks the effective horizon 1/(1 - gamma), where the weight has dropped to about 1/e. Raising gamma stretches that horizon, making the agent care about reward much further into the future.');
    state._render();
  }

  // ── policy-gradient-landscape: gradient ascent climbing a reward peak ──────
  function policyGradientLandscape(host) {
    var W = 520, H = 230, PAD = 30;
    var state = { lr: 0.15, steps: 14, theta0: -2.4 };
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // reward J(theta): a smooth peaked landscape with the maximum near theta = 1.2
    function J(t) { return 3 * Math.exp(-0.35 * (t - 1.2) * (t - 1.2)) + 0.4 * Math.exp(-0.8 * (t + 2) * (t + 2)); }
    function grad(t) { var h = 1e-3; return (J(t + h) - J(t - h)) / (2 * h); }
    function px(t) { return PAD + (t + 3.5) / 7 * (W - 2 * PAD); }
    function py(v) { return H - PAD - v / 3.4 * (H - 2 * PAD); }
    state._render = function () {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var d = '', i, x;
      for (i = 0; i <= 140; i++) { x = -3.5 + 7 * i / 140; d += (i ? 'L' : 'M') + px(x).toFixed(1) + ' ' + py(J(x)).toFixed(1) + ' '; }
      svg.appendChild(svgEl('path', { d: d, fill: 'none', stroke: 'var(--rule-soft,#ccc)', 'stroke-width': '2' }));
      var th = state.theta0, pts = [], t;
      for (t = 0; t <= state.steps; t++) { pts.push(th); th = th + state.lr * grad(th); th = clamp(th, -3.4, 3.4); }
      var pd = '';
      pts.forEach(function (p, idx) { pd += (idx ? 'L' : 'M') + px(p).toFixed(1) + ' ' + py(J(p)).toFixed(1) + ' '; });
      svg.appendChild(svgEl('path', { d: pd, fill: 'none', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '1.5', 'stroke-dasharray': '4 3' }));
      pts.forEach(function (p, idx) { svg.appendChild(svgEl('circle', { cx: px(p), cy: py(J(p)), r: idx === pts.length - 1 ? '5' : '3', fill: 'var(--blueprint,#3553ff)' })); });
      var last = pts[pts.length - 1];
      var atPeak = Math.abs(last - 1.2) < 0.2;
      status.innerHTML = atPeak ? 'reached the peak' : 'J(theta) = ' + J(last).toFixed(2);
      meta.textContent = 'theta = ' + last.toFixed(2) + '  ·  reward ' + J(last).toFixed(3) + ' of ' + J(1.2).toFixed(2) + ' max  ·  ' + (state.lr > 0.6 ? 'large lr: may overshoot the peak' : 'climbing');
      formula.textContent = 'theta <- theta + lr · grad_theta J(theta)   ·   ascent moves toward higher expected reward';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'lr', 'learning rate', 0.02, 1.0, 0.02),
      slider(state, 'steps', 'steps', 1, 40, 1),
      slider(state, 'theta0', 'start theta', -3.2, 3.2, 0.1)
    ]);
    frame(host, 'POLICY GRADIENT', 'drag the learning rate',
      grid, [svg, el('div', { style: 'margin-top:12px' }, [status]), meta, formula],
      'Policy gradient methods adjust the policy parameter theta in the direction that raises expected reward. Here the grey curve is the reward landscape and the dots are ascent steps climbing toward the peak. A small rate creeps up slowly; too large a rate overshoots; a local bump on the left can trap the climb if it starts there.');
    state._render();
  }

  LF.register({
    'diffusion-denoise': diffusionDenoise,
    'noise-schedule': noiseSchedule,
    'vae-latent-grid': vaeLatentGrid,
    'gan-minimax': ganMinimax,
    'qlearning-gridworld': qlearningGridworld,
    'value-iteration-gamma': valueIterationGamma,
    'epsilon-greedy': epsilonGreedy,
    'discount-horizon': discountHorizon,
    'policy-gradient-landscape': policyGradientLandscape
  });
})();

