      var g = svgEl('g', {}, [chip]);
      g.appendChild(seq('opacity', '0;0;1;0;0', '0;' + (0.1 + i * 0.11).toFixed(2) + ';' + (0.16 + i * 0.11).toFixed(2) + ';' + ta + ';1', D));
      svg.appendChild(fly(g, 'M182 ' + y + ' L338 ' + y, D, '0;0;1;1', '0;' + (0.1 + i * 0.11).toFixed(2) + ';' + ta + ';1'));
