    var mid = svgEl('line', { x1: 338, y1: 120, x2: 366, y2: 120, stroke: BP, 'stroke-width': '2', 'stroke-dasharray': '5 4' });
    mid.appendChild(anim('stroke-dashoffset', '18;0', '1s'));
