      cg.appendChild(svgEl('rect', { x: 378, y: c[1], width: 108, height: 22, rx: 4, fill: c[3] === BP ? BP : BG, 'fill-opacity': c[3] === BP ? '0.12' : '1', stroke: c[3], 'stroke-width': c[3] === BP ? '2' : '1.3' }));
      cg.appendChild(txt(432, c[1] + 15, c[0], c[4], 9));
