    var idx = [box(190, 168, 140, 30), txt(260, 187, 'multi-vector index', '9')];
    for (i = 0; i < 3; i++) { idx.push(line(cx[i] + 55, 142, 200 + i * 60, 168, SOFT)); }
    s.appendChild(pop(idx, 260, 183, D, '0.9s'));
