    s.appendChild(pop([box(185, 20, 150, 30), txt(260, 39, 'target verify pass', '9'), line(260, 50, 260, 92, SOFT, { 'stroke-dasharray': '4 3' })], 260, 35, D, '0.15s'));
    var words = ['def', 'main', '(', ')', ':'], tiles = [];
